const WEEKDAY_MAP={0:'Sunday',1:'Monday',2:'Tuesday',3:'Wednesday',4:'Thursday',5:'Friday',6:'Saturday'};
const APP_VERSION='12.1.0';
let state=loadState();
Finance.configure({getData:()=>state.finance,setData:value=>{state.finance=value},save:()=>{save();syncNativeReminders()},syncNow:()=>syncNow(),dateISO,timeISO,dhakaDate,requestNotifications:()=>requestNotifications(),showNotification:(title,options)=>showBrowserNotification(title,options)});
function dayKey(date){return WEEKDAY_MAP[new Date(date+'T12:00:00+06:00').getDay()]}
function loadState(){
 let s=JSON.parse(localStorage.getItem(APP_KEY)||'null');
 if(s)return migrate(s);
 let v10=JSON.parse(localStorage.getItem(V10_KEY)||'null');
 if(v10)return migrate(v10);
 let v9=JSON.parse(localStorage.getItem(V9_KEY)||'null');
 if(v9)return migrate(v9);
 let v8=JSON.parse(localStorage.getItem(V8_KEY)||'null');
 if(v8)return migrate(v8);
 let v7=JSON.parse(localStorage.getItem(V7_KEY)||'null');
 if(v7)return migrate(v7);
 let v6=JSON.parse(localStorage.getItem(V6_KEY)||'null');
 if(v6)return migrate(v6);
 let legacy=JSON.parse(localStorage.getItem(LEGACY_KEY)||'null');
 if(legacy)return migrate(legacy);
 let old=JSON.parse(localStorage.getItem(OLD_KEY)||'null');
 if(old)return migrate({startDate:old.startDate||dateISO(),records:old.records||{},daily:{},settings:{location:DEFAULTS.location}});
 return migrate({startDate:dateISO(),records:{},daily:{},settings:{...DEFAULTS.settings,location:DEFAULTS.location},weeklyTemplates:structuredClone(DEFAULTS.weeklyTemplates)});
}
function migrate(s){
 s.startDate=s.startDate||dateISO();s.records=s.records||{};s.daily=s.daily||{};s.settings=s.settings||{};s.settings.location=Object.assign({},DEFAULTS.location,s.settings.location||{});s.settings={...DEFAULTS.settings,...s.settings};
 s.finance=Finance.normalize(s.finance);
 Object.keys(s.daily).forEach(d=>{const day=s.daily[d]||{};if(!Array.isArray(day.extraTasks))day.extraTasks=[];delete day.tasks;});
 if(!s.weeklyTemplates){const legacy=s.template||null;s.weeklyTemplates={};DEFAULTS.weekdayOrder.forEach(d=>{if(legacy&&d!=='Friday'&&d!=='Saturday')s.weeklyTemplates[d]=structuredClone(legacy);else s.weeklyTemplates[d]=structuredClone(DEFAULTS.weeklyTemplates[d])});}
 DEFAULTS.weekdayOrder.forEach(d=>{if(!Array.isArray(s.weeklyTemplates[d]))s.weeklyTemplates[d]=structuredClone(DEFAULTS.weeklyTemplates[d])});
 delete s.template;return s;
}
function pruneEmptyRecords(){for(const d of Object.keys(state.records||{})){for(const id of Object.keys(state.records[d]||{})){const r=state.records[d][id];const keys=Object.keys(r||{}).filter(k=>k!=='status');if(r&&r.status==='pending'&&keys.length===0)delete state.records[d][id]}if(state.records[d]&&Object.keys(state.records[d]).length===0)delete state.records[d]}}
function loadSyncMeta(){try{return JSON.parse(localStorage.getItem(SYNC_LOCAL_KEY)||'null')||{enabled:false,code:'',initialized:false,entities:{},pending:{},clock:0,lastPull:0,lastPush:0,lastError:'',lastStatus:'Not connected'}}catch(e){return {enabled:false,code:'',initialized:false,entities:{},pending:{},clock:0,lastPull:0,lastPush:0,lastError:'',lastStatus:'Not connected'}}}
let syncMeta=loadSyncMeta();
syncMeta.entities=syncMeta.entities||{};
syncMeta.pending=syncMeta.pending||{};
syncMeta.rejected=syncMeta.rejected||{};
function saveSyncMeta(){localStorage.setItem(SYNC_LOCAL_KEY,JSON.stringify(syncMeta))}
function cloneForSync(value){return structuredClone(value)}
function syncDailyValue(day){const d=day||{},v={};if(Array.isArray(d.extraTasks)&&d.extraTasks.length)v.extraTasks=cloneForSync(d.extraTasks);if(d.games)v.games=cloneForSync(d.games);return v}
function collectSyncEntities(){
 const out={startDate:state.startDate,settings:cloneForSync(state.settings||{}),...Finance.collectSyncEntities(state.finance)};
 for(const d of DEFAULTS.weekdayOrder)out['schedule:'+d]=cloneForSync((state.weeklyTemplates||{})[d]||[]);
 for(const d of Object.keys(state.records||{})){for(const id of Object.keys(state.records[d]||{})){out['record:'+d+':'+id]=cloneForSync(state.records[d][id]);}}
 for(const d of Object.keys(state.daily||{})){const v=syncDailyValue(state.daily[d]);if(v&&Object.keys(v).length)out['daily:'+d]=v;}
 return out;
}
function syncStamp(){const n=Date.now();syncMeta.clock=Math.max(n,(Number(syncMeta.clock)||0)+1);return syncMeta.clock}
function markLocalSyncChanges(){
 if(!syncMeta.enabled||!syncMeta.code)return;
 syncMeta.entities=syncMeta.entities||{};syncMeta.pending=syncMeta.pending||{};syncMeta.rejected=syncMeta.rejected||{};
 const current=collectSyncEntities(), previous=syncMeta.entities||{}, keys=new Set([...Object.keys(previous),...Object.keys(current)]);
 for(const key of keys){
   const exists=Object.prototype.hasOwnProperty.call(current,key);
   const value=exists?current[key]:null;
   const hash=exists?JSON.stringify(value):null;
   const prev=previous[key];
   if(!prev || prev.hash!==hash || !!prev.deleted===exists){
     const updatedAt=syncStamp();
     previous[key]={hash,updatedAt,deleted:!exists};
     syncMeta.pending[key]={key,updatedAt,deleted:!exists,value};
     delete syncMeta.rejected[key];
   }
 }
 syncMeta.entities=previous;saveSyncMeta();
}
function save(opts={}){pruneEmptyRecords();localStorage.setItem(APP_KEY,JSON.stringify(state));if(opts.trackChanges!==false)markLocalSyncChanges();if(opts.queue!==false)queueCloudPush()}
let syncPushTimer=null;let syncBusy=false;
function queueCloudPush(){if(!syncMeta.enabled||!syncMeta.code)return;clearTimeout(syncPushTimer);syncPushTimer=setTimeout(()=>syncPushPending(),500)}
function syncStatusText(){if(!syncMeta.enabled)return 'Not connected';if(syncMeta.lastError)return 'Sync error: '+syncMeta.lastError;if(syncMeta.lastPull)return 'Connected · last sync '+DHAKA_STATUS_TIME_FORMATTER.format(new Date(syncMeta.lastPull));return 'Connected · syncing…'}
function updateSyncStatusUI(){const text=syncStatusText();const el=document.getElementById('syncStatus');if(el){el.textContent=text;el.className='mini '+(syncMeta.enabled&&!syncMeta.lastError?'success':'notice')}const badge=document.getElementById('syncBadge');if(badge){if(!navigator.onLine){badge.textContent='☁ Offline';badge.className='syncbadge err';}else if(!syncMeta.enabled){badge.textContent='☁ Not connected';badge.className='syncbadge off';}else if(syncBusy){badge.textContent='☁ Syncing…';badge.className='syncbadge syncing';}else if(syncMeta.lastError){badge.textContent='☁ Sync issue';badge.className='syncbadge err';}else{const when=syncMeta.lastPull?DHAKA_STATUS_TIME_FORMATTER.format(new Date(syncMeta.lastPull)):'—';badge.textContent='☁ Synced '+when;badge.className='syncbadge ok';}}}
function normalizedSyncCode(v){return String(v||'').trim().toUpperCase().replace(/[^A-Z0-9]/g,'')}
function generateSyncCode(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';try{if(!window.crypto?.getRandomValues)throw new Error('Secure random numbers are unavailable.');const bytes=window.crypto.getRandomValues(new Uint8Array(20));let out='';for(const byte of bytes)out+=chars[byte%chars.length];const el=document.getElementById('syncCode');if(el)el.value=out;return out}catch(e){alert('A secure pairing code could not be generated. Open the app over HTTPS and try again.');return ''}}
async function syncRequest(action,changes=[]){
 const code=normalizedSyncCode(syncMeta.code);if(!code)return {ok:false,error:'No sync code'};
 const endpoint=window.Capacitor?.isNativePlatform?.()?NATIVE_SYNC_API:SYNC_API;
 const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},cache:'no-store',body:JSON.stringify({action,code,changes})});
 const j=await r.json().catch(()=>({ok:false,error:'Invalid sync response'}));if(!r.ok||!j.ok)throw new Error(j.error||('Sync HTTP '+r.status));return j;
}
function syncChangeBatches(changes){
 const batches=[];let batch=[],bytes=0;
 for(const change of changes){
   const size=new TextEncoder().encode(JSON.stringify(change)).length+1;
   if(batch.length&&(batch.length>=MAX_SYNC_BATCH_CHANGES||bytes+size>MAX_SYNC_BATCH_BYTES)){
     batches.push(batch);batch=[];bytes=0;
   }
   batch.push(change);bytes+=size;
 }
 if(batch.length)batches.push(batch);
 return batches;
}
function applySyncEntity(key,deleted,value){
 if(key==='startDate'){if(deleted)return false;state.startDate=String(value||state.startDate);return true;}
 if(key==='settings'){if(deleted)return false;state.settings={...DEFAULTS.settings,...cloneForSync(value||{}),location:{...DEFAULTS.location,...((value&&value.location)||{})}};return true;}
 if(key==='finance'){if(deleted)return false;state.finance=Finance.importLegacy(state.finance,value);return true;}
 if(key.startsWith('finance:')){state.finance=Finance.applySyncEntity(state.finance,key,deleted,value);return true;}
 if(key.startsWith('schedule:')){const d=key.slice(9);if(!DEFAULTS.weekdayOrder.includes(d))return false;if(deleted)state.weeklyTemplates[d]=[];else state.weeklyTemplates[d]=cloneForSync(value||[]);return true;}
 if(key.startsWith('record:')){const parts=key.split(':');const d=parts[1],id=parts.slice(2).join(':');if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||!id)return false;if(!state.records[d])state.records[d]={};if(deleted){delete state.records[d][id];if(!Object.keys(state.records[d]).length)delete state.records[d];}else state.records[d][id]=cloneForSync(value||{});return true;}
 if(key.startsWith('daily:')){const d=key.slice(6);if(deleted)delete state.daily[d];else {state.daily[d]=cloneForSync(value||{});delete state.daily[d].tasks;delete state.daily[d].prayers;}return true;}
 return false;
}
function hasMeaningfulLocalData(){return Object.keys(state.records||{}).length>0||Finance.hasMeaningfulData(state.finance)||Object.keys(state.daily||{}).some(d=>Object.keys(syncDailyValue(state.daily[d])).length>0)||JSON.stringify(state.weeklyTemplates)!==JSON.stringify(DEFAULTS.weeklyTemplates)}
function seedLocalSyncMeta(ts){syncMeta.entities={};syncMeta.pending={};syncMeta.clock=Number(ts)||Date.now();for(const [key,value] of Object.entries(collectSyncEntities()))syncMeta.entities[key]={hash:JSON.stringify(value),updatedAt:syncStamp(),deleted:false};saveSyncMeta()}
async function pushAllLocal(){
 const current=collectSyncEntities();syncMeta.pending={};syncMeta.rejected={};
 for(const [key,value] of Object.entries(current)){const updatedAt=syncStamp();syncMeta.entities[key]={hash:JSON.stringify(value),updatedAt,deleted:false};syncMeta.pending[key]={key,updatedAt,deleted:false,value};}
 saveSyncMeta();const uploaded=await syncPushPending();
 if(!uploaded)throw new Error(syncMeta.lastError||'Some local changes are still waiting to sync.');
 return true;
}
async function syncPushPending(){
 if(syncBusy||!syncMeta.enabled||!syncMeta.code)return false;
 const pending=Object.values(syncMeta.pending||{}),changes=pending.filter(change=>syncMeta.rejected[change.key]?.updatedAt!==change.updatedAt);
 if(!changes.length){updateSyncStatusUI();return pending.length===0;}
 syncBusy=true;syncMeta.lastError='';saveSyncMeta();
 try{
   for(const batch of syncChangeBatches(changes)){
     const res=await syncRequest('push',batch);
     if(!Array.isArray(res.acceptedKeys)||!Array.isArray(res.rejected))throw new Error('The sync server did not confirm which changes were saved.');
     const batchByKey=new Map(batch.map(change=>[change.key,change]));
     for(const key of res.acceptedKeys){
       const sent=batchByKey.get(key),current=syncMeta.pending[key];
       if(sent&&current&&current.updatedAt===sent.updatedAt){delete syncMeta.pending[key];delete syncMeta.rejected[key];}
     }
     const failures=[];
     for(const rejection of res.rejected){
       const sent=batchByKey.get(rejection?.key),current=syncMeta.pending[rejection?.key];
       if(!sent||!current||current.updatedAt!==sent.updatedAt)continue;
       if(rejection.reason==='stale'){
         syncMeta.lastError='A newer cloud version was found; it will be merged on the next sync.';
       }else{
         syncMeta.rejected[sent.key]={updatedAt:sent.updatedAt,reason:String(rejection.reason||'rejected')};
         failures.push(`${sent.key}: ${rejection.reason||'rejected'}`);
       }
     }
     if(failures.length)syncMeta.lastError=`Cloud rejected ${failures.length} change${failures.length===1?'':'s'}; local data remains saved. ${failures.slice(0,3).join('; ')}`;
     syncMeta.lastPush=Date.now();saveSyncMeta();
   }
   return Object.keys(syncMeta.pending).length===0;
 }catch(e){
   syncMeta.lastError=String(e.message||e);syncMeta.lastStatus='Sync error';saveSyncMeta();updateSyncStatusUI();return false;
 }finally{syncBusy=false;updateSyncStatusUI();}
}
async function pullAndMerge(renderOnChange=true){
 if(!syncMeta.enabled||!syncMeta.code||syncBusy)return;
 syncBusy=true;let changed=false;syncMeta.lastError='';
 try{const res=await syncRequest('pull');const cloud=Object.fromEntries((res.entities||[]).map(x=>[x.key,x]));
   const localMeta=syncMeta.entities||{};const localChanges=Object.keys(syncMeta.pending||{});
   for(const [key,entry] of Object.entries(cloud)){
     const lm=localMeta[key];const localPending=syncMeta.pending[key];
     if(!lm || Number(entry.updatedAt)>Number(lm.updatedAt) || (Number(entry.updatedAt)===Number(lm.updatedAt)&&localPending&&!entry.deleted)){
       if(applySyncEntity(key,entry.deleted,entry.value))changed=true;
       const hash=entry.deleted?null:JSON.stringify(entry.value);localMeta[key]={hash,updatedAt:Number(entry.updatedAt)||Date.now(),deleted:!!entry.deleted};delete syncMeta.pending[key];delete syncMeta.rejected[key];
     }
   }
   if(window.__financeLegacyImportOccurred){window.__financeLegacyImportOccurred=false;markLocalSyncChanges();}
   // Anything local/newer that the cloud does not have stays pending and will be uploaded.
   syncMeta.entities=localMeta;syncMeta.lastPull=Date.now();syncMeta.lastError='';saveSyncMeta();
   if(changed){save({trackChanges:false,queue:false});for(const d of Object.keys(state.daily||{}))delete state.daily[d].tasks;ensureDay(dateISO());try{syncNativeReminders();}catch(e){}if(renderOnChange)render();}
 }catch(e){syncMeta.lastError=String(e.message||e);saveSyncMeta();}finally{syncBusy=false;updateSyncStatusUI();}
}
async function connectSync(){
 pruneEmptyRecords();
 const raw=document.getElementById('syncCode')?.value||'';const code=normalizedSyncCode(raw);
 if(code.length<8){alert('Use an 8–32 character sync code.');return;}
 syncMeta.code=code;syncMeta.enabled=true;syncMeta.lastError='';saveSyncMeta();
 try{const res=await syncRequest('pull');
   if((res.entities||[]).length===0){seedLocalSyncMeta(Date.now());await pushAllLocal();alert('Cloud sync created. Use the same code on your other device.');}
   else if(!syncMeta.initialized){
     if(hasMeaningfulLocalData()) {const useCloud=confirm('Cloud data was found. Press OK to download the cloud data to this device. Press Cancel to keep this device and upload it to the cloud.');if(useCloud){for(const e of res.entities||[]){applySyncEntity(e.key,e.deleted,e.value);syncMeta.entities[e.key]={hash:e.deleted?null:JSON.stringify(e.value),updatedAt:Number(e.updatedAt)||Date.now(),deleted:!!e.deleted};delete syncMeta.pending[e.key];}save({trackChanges:false,queue:false});}else{await pushAllLocal();}}
     else {for(const e of res.entities||[]){applySyncEntity(e.key,e.deleted,e.value);syncMeta.entities[e.key]={hash:e.deleted?null:JSON.stringify(e.value),updatedAt:Number(e.updatedAt)||Date.now(),deleted:!!e.deleted};delete syncMeta.pending[e.key];}save({trackChanges:false,queue:false});}
   }
   if(window.__financeLegacyImportOccurred){window.__financeLegacyImportOccurred=false;markLocalSyncChanges();await syncPushPending();}
   syncMeta.initialized=true;syncMeta.lastPull=Date.now();saveSyncMeta();syncNativeReminders();render();alert('Cloud sync connected. This device will sync automatically.');
 }catch(e){syncMeta.lastError=String(e.message||e);saveSyncMeta();updateSyncStatusUI();alert('Sync connection failed: '+syncMeta.lastError);}
}
