function pad(n){return String(n).padStart(2,'0')}
function mins(s){let [h,m]=String(s).split(':').map(Number);return h*60+m}
function time(m){m=((m%1440)+1440)%1440;return pad(Math.floor(m/60))+':'+pad(m%60)}
function parseClockInput(v){v=String(v||'').trim().toUpperCase().replace(/\s+/g,' ');let m=v.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/);if(m){let h=Number(m[1]),mm=Number(m[2]);if(h<1||h>12||mm>59)return null;if(m[3]==='PM'&&h<12)h+=12;if(m[3]==='AM'&&h===12)h=0;return h*60+mm}m=v.match(/^(\d{1,2}):(\d{2})$/);if(m){let h=Number(m[1]),mm=Number(m[2]);if(h>23||mm>59)return null;return h*60+mm}m=v.match(/^(\d{1,2})\s*(AM|PM)$/);if(m){let h=Number(m[1]);if(h<1||h>12)return null;if(m[2]==='PM'&&h<12)h+=12;if(m[2]==='AM'&&h===12)h=0;return h*60}return null}
function time12(s,seconds=false){if(!s)return '--';let [h,m]=s.split(':').map(Number);let ap=h>=12?'PM':'AM';h=h%12||12;return h+':'+pad(m)+(seconds?':'+pad(new Date().getSeconds()):'')+' '+ap}
function timeRange12(start,dur){if(!start)return '--';const end=time(mins(start)+(Number(dur)||0));return time12(start)+' – '+time12(end)}
function formatDuration(value){let n=Math.max(0,Math.round(Number(value)||0));if(n<60)return n+'m';const h=Math.floor(n/60),m=n%60;return m?h+'h '+m+'m':h+'h'}
function dateISO(d=new Date()){return DHAKA_DATE_FORMATTER.format(d)}
function timeISO(d=new Date()){const p=DHAKA_TIME_PARTS_FORMATTER.formatToParts(d);return `${p.find(x=>x.type==='hour').value}:${p.find(x=>x.type==='minute').value}`}
function dateLabel(d){return DHAKA_DATE_LABEL_FORMATTER.format(new Date(d+'T12:00:00+06:00'))}
function dayNo(dateStr){let a=new Date(state.startDate+'T00:00:00+06:00'),b=new Date(dateStr+'T00:00:00+06:00');return Math.floor((b-a)/86400000)+1}
function planNotStarted(){return dateISO()<state.startDate}
function currentDay(){if(planNotStarted())return 0;return Math.min(180,Math.max(1,dayNo(dateISO())))}
function dayComplete(date){const tasks=tasksFor(date);return tasks.length>0&&tasks.every(t=>getRec(date,t.id).status==='done')}
function roadmapState(day){if(planNotStarted())return 'locked';const d=addDaysISO(state.startDate,day-1);if(d===dateISO())return dayComplete(d)?'complete':'today';if(d<dateISO())return dayComplete(d)?'complete':'incomplete';return 'future'}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function nowDhaka(){return new Date()}
function nowMinutes(){let p=DHAKA_MINUTES_FORMATTER.formatToParts(new Date()),o={};p.forEach(x=>o[x.type]=x.value);return Number(o.hour)*60+Number(o.minute)+Number(o.second)/60}
function isFriday(date){return new Date(date+'T12:00:00+06:00').getDay()===5}
function isSaturday(date){return new Date(date+'T12:00:00+06:00').getDay()===6}
function getRec(date,id){state.records[date]=state.records[date]||{};state.records[date][id]=state.records[date][id]||{status:'pending'};return state.records[date][id]}
function getDay(date){state.daily[date]=state.daily[date]||{};return state.daily[date]}
function addDaysISO(dateStr,n){const d=new Date(dateStr+'T12:00:00+06:00');d.setTime(d.getTime()+n*86400000);return dateISO(d)}
function prevDateISO(dateStr=dateISO()){return addDaysISO(dateStr,-1)}
function dhakaDate(dateStr,hhmm){const t=String(hhmm||'00:00').slice(0,5);return new Date(dateStr+'T'+t+':00+06:00')}
function windowEndMs(date,t,r){const start=dhakaDate(date,r.plannedStart??t.start);return start.getTime()+(Number(r.plannedDur??t.dur)||0)*60000}
function windowStartMs(date,t,r){return dhakaDate(date,r.plannedStart??t.start).getTime()}
function isLockedStatus(st){return st==='done'||st==='missed'}
function windowEnded(date,t,r,at=Date.now()){return at>=windowEndMs(date,t,r)}
function windowActive(date,t,r,at=Date.now()){const a=windowStartMs(date,t,r),b=windowEndMs(date,t,r);return at>=a&&at<b}
function prayerTimes(date){return getDay(date).prayers||null}
async function fetchPrayerTimes(date,force=false){
 const d=getDay(date);if(d.prayers&&!force)return d.prayers;
 const L=state.settings.location||DEFAULTS.location;
 const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),7000);
 try{
  const u='https://api.aladhan.com/v1/timings/'+date.split('-').reverse().join('-')+'?latitude='+encodeURIComponent(L.lat)+'&longitude='+encodeURIComponent(L.lon)+'&method='+encodeURIComponent(L.method)+'&school='+encodeURIComponent(L.school);
  const r=await fetch(u,{cache:'no-store',signal:controller.signal});if(!r.ok)throw new Error('Prayer API '+r.status);const j=await r.json();const t=j?.data?.timings;if(!t?.Fajr)throw new Error('Prayer data unavailable');
  d.prayers={Fajr:t.Fajr.slice(0,5),Sunrise:t.Sunrise.slice(0,5),Dhuhr:t.Dhuhr.slice(0,5),Asr:t.Asr.slice(0,5),Maghrib:t.Maghrib.slice(0,5),Isha:t.Isha.slice(0,5)};d.prayerSource='AlAdhan';delete d.prayerError;delete d.tasks;save();return d.prayers;
 }catch(e){d.prayerError=e.name==='AbortError'?'Prayer service timeout':String(e.message||e);save();return d.prayers||null}
 finally{clearTimeout(timer)}
}
function cloneTemplateTasks(key){return structuredClone(state.weeklyTemplates[key]||DEFAULTS.weeklyTemplates[key]||[])}
function recoveryMissionTasks(date,existing){
 if(!isSaturday(date))return [];
 const prev=addDaysISO(date,-1),ws=weeklyStats(prev);
 if(ws.possible===0||ws.score>=80)return [];
 const used=existing.map(t=>[mins(t.start),mins(t.start)+(Number(t.dur)||0)]);
 const missions=[
  {id:'recovery-kanji',name:'Recovery · Kanji / Kana drill',kind:'recovery',dur:10},
  {id:'recovery-listen',name:'Recovery · Japanese listening',kind:'recovery',dur:15},
  {id:'recovery-workout',name:'Recovery · 10-minute mobility',kind:'recovery',dur:10}
 ];
 const gaps=[]; for(let m=8*60;m<21*60;m+=5){let ok=true;for(const [a,b] of used)if(m<b+5&&m+15>a-5){ok=false;break}if(ok)gaps.push(m)}
 const out=[];let cursor=0;for(const ms of missions){const idx=gaps.findIndex(x=>x>=cursor);if(idx<0)break;const st=gaps[idx];out.push({...ms,start:time(st),flex:true,bonus:true});cursor=st+ms.dur+10;used.push([st,st+ms.dur]);}
 return out;
}
function baseSchedule(date,includeRecovery=true){
 const key=dayKey(date),prayers=Object.assign({Fajr:'04:45',Dhuhr:'12:10',Asr:'15:30',Maghrib:'18:15',Isha:'19:35'},prayerTimes(date)||{}),raw=cloneTemplateTasks(key);
 const byPrayer={}; raw.forEach(t=>{if(t.prayer)byPrayer[t.prayer]=t});
 const a=raw.map(t=>{const x=structuredClone(t);if(x.prayer&&!x.manualStart){x.start=prayers[x.prayer]||x.start||'00:00';}if(x.prayer==='Dhuhr'&&key==='Friday'&&!x.manualName)x.name="Jumu'ah";else if(x.after){const base=prayers[x.after];if(base)x.start=time(mins(base)+(Number(x.offset)||0));}x.start=x.start||'00:00';return x}).filter(t=>Number(t.dur||0)>0).sort((x,y)=>mins(x.start)-mins(y.start));
 const recover=includeRecovery?recoveryMissionTasks(date,a):[];return [...a,...recover].sort((x,y)=>mins(x.start)-mins(y.start));
}
function tasksFor(date){const day=getDay(date);const base=baseSchedule(date);const extras=Array.isArray(day.extraTasks)?day.extraTasks:[];day.tasks=[...base,...extras].sort((a,b)=>mins(a.start||'00:00')-mins(b.start||'00:00'));return day.tasks;}
function ensureDay(date){tasksFor(date);return getDay(date)}
function runningTasks(date=dateISO()){const out=[];const dates=[date,prevDateISO(date)];for(const d of dates){const recs=state.records[d]||{};for(const id of Object.keys(recs)){const r=recs[id];if(r.status!=='running')continue;const t=tasksFor(d).find(x=>x.id===id)||{id,name:id,start:r.plannedStart||'00:00',dur:r.plannedDur||0};out.push({date:d,t,r});}}return out;}
function runningTaskById(id){return runningTasks().find(x=>x.t.id===id)||null;}
function invalidateWeekdaySchedule(key){for(const d of Object.keys(state.daily||{})){if(d>=dateISO()&&dayKey(d)===key){delete state.daily[d].tasks;}}}
function setWeekdayTemplate(key,items){state.weeklyTemplates[key]=items.slice().sort((a,b)=>mins(a.start||'00:00')-mins(b.start||'00:00'));invalidateWeekdaySchedule(key);save();syncNativeReminders();render();}
function statusFor(t,date){
 const r=getRec(date,t.id);
 if(t.prayer&&!prayerTimes(date)&&date===dateISO())return 'pending';
 if(state.settings.resetFresh&&date===state.startDate&&r.status==='pending')return 'pending';
 if(r.status==='done'||r.status==='missed'||r.status==='running')return r.status;
 if(windowEnded(date,t,r)){r.status='missed';r.autoMissed=true;r.locked=true;r.reason=r.reason||'Automatically missed: scheduled window ended without start.';save();return 'missed';}
 if(date===dateISO()&&windowActive(date,t,r)&&Date.now()>windowStartMs(date,t,r)+60000)return 'overdue';
 return 'pending';
}
function findRunning(){return runningTasks()[0]||null;}
function expireElapsedTasks(date=dateISO()){
 if(!date||date>dateISO())return false;
 if(!prayerTimes(date))return false;
 if(state.settings.resetFresh&&date===state.startDate)return false;
 const tasks=tasksFor(date);let changed=false;const now=Date.now();
 for(const t of tasks){
  const r=getRec(date,t.id);
  if(r.status!=='pending')continue;
  if(now>=windowEndMs(date,t,r)){
   r.status='missed';r.autoMissed=true;r.locked=true;
   r.reason=r.reason||'Automatically missed: scheduled window ended without start.';
   r.expiredAt=new Date().toISOString();changed=true;
  }
 }
 if(changed)save();
 return changed;
}
function expireDueTasks(){
 if(state.settings.resetFresh)return false;
 const today=dateISO();
 return !!(expireElapsedTasks(prevDateISO(today))|expireElapsedTasks(today));
}
function missTask(id){
 const date=dateISO(),t=tasksFor(date).find(x=>x.id===id),r=getRec(date,id);
 if(!t||isLockedStatus(r.status)||r.status==='running')return;
 r.status='missed';r.locked=true;r.manualMiss=true;r.reason='Marked missed';r.at=new Date().toISOString();
 save();refreshTaskUI();
}
function editTaskById(id,date=dateISO()){
 const tasks=tasksFor(date),t=tasks.find(x=>x.id===id),r=t?getRec(date,t.id):null;
 if(!t)return;
 if(isLockedStatus(r.status))return alert('This task is locked and cannot be edited.');
 if(r.status==='running')return alert('Stop the running task before editing it.');
 let name=prompt('Task name',t.name);if(name===null)return;let st=prompt('Start time (e.g. 8:00 PM or 20:00)',time12(t.start));if(st===null)return;let dur=prompt('Duration in minutes',r.plannedDur??t.dur);if(dur===null)return;
 const parsed=parseClockInput(st);if(parsed===null)return alert('Use a time like 8:00 PM or 20:00.');t.name=name;t.start=time(parsed);r.plannedDur=Math.max(0,Number(dur)||t.dur);r.plannedStart=t.start;save();refreshTaskUI();
}
function editTask(i,date=dateISO()){const t=tasksFor(date)[i];if(t)editTaskById(t.id,date);}
function addTask(date=dateISO()){
 let name=prompt('Today-only task name');if(!name)return;
 let st=prompt('Start time (e.g. 8:00 PM or 20:00)','8:00 PM');if(!st)return;
 const parsed=parseClockInput(st);if(parsed===null)return alert('Use a time like 8:00 AM, 8:00 PM or 20:00.');
 let dur=Number(prompt('Duration in minutes','30'));if(!Number.isFinite(dur)||dur<1)return alert('Duration must be at least 1 minute.');
 const day=getDay(date);day.extraTasks=Array.isArray(day.extraTasks)?day.extraTasks:[];
 day.extraTasks.push({id:'temp-'+date+'-'+Date.now(),name:name.trim(),start:time(parsed),dur:Math.round(dur),kind:'temporary',flex:true,temporary:true});
 save();syncNativeReminders();render();
}
function setDailyPlanned(t,r){r.plannedDur=r.plannedDur??t.dur;r.plannedStart=r.plannedStart??t.start}
function startTask(id){
 primeWebReminderAudio();
 if(!window.AndroidBridge && 'Notification' in window && Notification.permission==='default') requestNotifications();
 expireDueTasks();
 const date=dateISO(),tasks=tasksFor(date),t=tasks.find(x=>x.id===id),r=getRec(date,id);
 if(!t)return;
 if(isLockedStatus(r.status)||r.status==='running')return;
 if(windowEnded(date,t,r)){expireElapsedTasks(date);refreshTaskUI();return;}
 const active=runningTasks();
 if(active.length>=3)return alert('Maximum 3 tasks can run at the same time. Stop one running task before starting another.');
 setDailyPlanned(t,r);
 if(state.settings.resetFresh&&date===state.startDate)state.settings.resetFresh=false;
 r.status='running';r.date=date;r.taskId=id;
 r.actualStart=new Date().toISOString();
 r.actualStartClock=time12(time(Math.floor(nowMinutes())));
 r.lateStartMin=Math.max(0,Math.round((Date.now()-windowStartMs(date,t,r))/60000));
 r.plannedStart=r.plannedStart??t.start;r.plannedDur=r.plannedDur??t.dur;
 save();refreshTaskUI();
}
function absorbOvertime(date,index,debt){
 if(debt<=0)return 0;let tasks=tasksFor(date),remaining=Math.round(debt);
 for(let i=index+1;i<tasks.length&&remaining>0;i++){
  const nt=tasks[i],nr=getRec(date,nt.id);
  if(isLockedStatus(nr.status)||nr.status==='running')continue;
  if(nt.prayer||nt.flex===false)continue;
  setDailyPlanned(nt,nr);const old=Number(nr.plannedDur??nt.dur)||0;const cut=Math.min(old,remaining);
  nr.plannedDur=old-cut;nr.delayApplied=(nr.delayApplied||0)+cut;remaining-=cut;
  if(nr.plannedDur<=0){nr.plannedDur=0;nr.status='missed';nr.locked=true;nr.reason='Automatically missed: schedule delay consumed the full task.';nr.autoMissed=true;}
  break;
 }
 return Math.round(debt-remaining);
}
function stopTaskBase(id,silent=false){
 let found=runningTaskById(id);
 if(!found||!found.t||found.r.status!=='running')return;
 const {date,t,r}=found;
 const now=new Date(),actualStop=now.toISOString(),actualDur=Math.max(0,Math.round((now-new Date(r.actualStart))/60000));
 r.status='done';r.locked=true;r.actualStop=actualStop;r.actualDuration=actualDur;
 r.stopClock=DHAKA_STATUS_TIME_FORMATTER.format(now);
 const overtime=Math.max(0,Math.round((now.getTime()-windowEndMs(date,t,r))/60000));r.overtimeMin=overtime;
 const tasks=tasksFor(date),idx=tasks.findIndex(x=>x.id===id);
 if(overtime>0&&idx>=0)r.adjustedNextMin=absorbOvertime(date,idx,overtime);
 save();
 if(!silent){
  if(date!==dateISO()){ensureDay(dateISO());fetchPrayerTimes(dateISO()).then(()=>{const d=getDay(dateISO());d.tasks=null;ensureDay(dateISO());render()});}
  render();
 }
}
function openLateModal(){
 const date=dateISO(),tasks=tasksFor(date);let runningIndex=tasks.findIndex(t=>getRec(date,t.id).status==='running');
 let nextIdx=runningIndex>=0?runningIndex+1:tasks.findIndex(t=>{const st=getRec(date,t.id).status;return st!=='done'&&st!=='missed'});
 if(nextIdx<0||!tasks[nextIdx])return alert('No active/upcoming task found.');
 window.lateTargetIndex=nextIdx;const t=tasks[nextIdx],r=getRec(date,t.id);setDailyPlanned(t,r);
 document.getElementById('lateNextTask').textContent=t.name+' · '+time12(t.start)+' · '+formatDuration(r.plannedDur??t.dur);
 document.getElementById('lateMinutes').value=Math.max(1,Math.round(Math.max(0,nowMinutes()-mins(t.start)))||10);
 document.getElementById('lateModal').classList.remove('hidden');renderLateClock();
}
function closeLateModal(){document.getElementById('lateModal').classList.add('hidden')}
function renderLateClock(){const m=document.getElementById('lateModal');if(!m||m.classList.contains('hidden'))return;document.getElementById('lateClock').textContent=DHAKA_CLOCK_FORMATTER.format(new Date())}
function applyLate(){
 const date=dateISO(),tasks=tasksFor(date),next=Number(window.lateTargetIndex);if(next<0||!tasks[next])return;const delay=Math.max(0,Math.round(Number(document.getElementById('lateMinutes').value)||0));if(!delay)return alert('Enter at least 1 minute.');
 const applied=absorbOvertime(date,next-1,delay);const target=tasks[next],tr=getRec(date,target.id);tr.delayAt=new Date().toISOString();tr.delayRequested=delay;tr.delaySource='running late button';if(applied<delay)tr.unabsorbedDelay=delay-applied;
 let cursor=mins(target.start)+(tr.plannedDur??target.dur);for(let i=next+1;i<tasks.length;i++){const nt=tasks[i],nr=getRec(date,nt.id);if(nr.status==='done'||nr.status==='missed')continue;if(nt.prayer)break;if(nt.flex){nt.start=time(cursor);cursor=mins(nt.start)+(nr.plannedDur??nt.dur)}}
 save();closeLateModal();render();
}

function upcoming(date){
 expireElapsedTasks(date);
 const tasks=tasksFor(date),now=Date.now();
 const active=tasks.find(t=>getRec(date,t.id).status==='pending'&&windowActive(date,t,getRec(date,t.id),now));
 if(active)return active;
 return tasks.find(t=>getRec(date,t.id).status==='pending'&&windowStartMs(date,t,getRec(date,t.id))>now&&!windowEnded(date,t,getRec(date,t.id),now))||null;
}
function upcomingExcludingCurrent(date){
 expireElapsedTasks(date);
 const runningIds=new Set(runningTasks(date).map(x=>x.t.id));
 const tasks=tasksFor(date),now=Date.now();
 const active=tasks.find(t=>!runningIds.has(t.id)&&getRec(date,t.id).status==='pending'&&windowActive(date,t,getRec(date,t.id),now));
 if(active)return active;
 return tasks.find(t=>!runningIds.has(t.id)&&getRec(date,t.id).status==='pending'&&windowStartMs(date,t,getRec(date,t.id))>now&&!windowEnded(date,t,getRec(date,t.id),now))||null;
}
function completion(date){const tasks=tasksFor(date),done=tasks.filter(t=>getRec(date,t.id).status==='done').length,missed=tasks.filter(t=>getRec(date,t.id).status==='missed').length;return {done,missed,total:tasks.length,pct:tasks.length?Math.round(done/tasks.length*100):0}}
function renderClock(){const d=new Date(),parts=DHAKA_CLOCK_FORMATTER.formatToParts(d),o={};parts.forEach(x=>o[x.type]=x.value);document.getElementById('liveClock').textContent=`${o.hour}:${o.minute}:${o.second} ${o.dayPeriod}`;document.getElementById('liveDate').textContent=DHAKA_LIVE_DATE_FORMATTER.format(d)+' · Bangladesh time'}
function weekStartSat(date){const d=new Date(date+'T12:00:00+06:00');const dow=d.getDay();d.setDate(d.getDate()-((dow+1)%7));return dateISO(d)}
function weeklyDates(start){return Array.from({length:7},(_,i)=>addDaysISO(start,i))}
function dayPerfect(date){const tasks=baseSchedule(date,false);return tasks.length>0&&tasks.every(t=>getRec(date,t.id).status==='done')}
function weeklyStats(anchor){const start=weekStartSat(anchor),dates=weeklyDates(start),anchorDate=anchor;let earned=0,possible=0,done=0,missed=0;for(const d of dates){if(d<state.startDate||d>anchorDate)continue;const tasks=baseSchedule(d,false);for(const t of tasks){possible+=10;const r=state.records[d]&&state.records[d][t.id];if(r?.status==='done'){done++;earned+=10;if((r.overtimeMin||0)===0)earned+=1;}else if(r?.status==='missed'){missed++;}}}const score=possible?Math.round(Math.min(100,earned/possible*100)):0;return {start,dates,earned,possible,score,done,missed}}
function progressStats(){let xp=0,perfect=0,totalDays=0,completedDays=0;for(const d of Object.keys(state.records||{})){const tasks=baseSchedule(d,false);if(!tasks.length)continue;totalDays++;let all=true,anyDone=false;for(const t of tasks){const r=state.records[d]?.[t.id];if(!r||r.status!=='done'){all=false;continue;}anyDone=true;xp+=10;if((r.overtimeMin||0)===0)xp+=1;if(t.kind==='japanese')xp+=3;}if(all&&anyDone){perfect++;completedDays++;xp+=25;}}const seenWeeks=new Set();for(const d of Object.keys(state.records||{})){const ws=weeklyStats(d);if(ws.possible&&!seenWeeks.has(ws.start)){seenWeeks.add(ws.start);if(ws.score>=80)xp+=50;}}const level=Math.max(1,Math.min(100,Math.floor(xp/120)+1)),inLevel=xp%120;return {xp,level,inLevel,perfect,totalDays,completedDays}}
let webReminderTimers=new Map(),webReminderFired=new Set(),webAudioCtx=null,browserServiceWorkerReady=null;
function notificationDeliveryMode(protocol=location.protocol){
 return !window.AndroidBridge&&'serviceWorker'in navigator&&protocol!=='file:'&&isSecureContext?'service-worker':'page';
}
function ensureBrowserServiceWorker(){
 if(notificationDeliveryMode()==='page')return Promise.reject(new Error(location.protocol==='file:'?'Service workers are unavailable when this app is opened as a local file.':'This browser does not support service-worker notifications on this origin.'));
 if(!browserServiceWorkerReady){
   const registration=navigator.serviceWorker.register('./sw.js').then(reg=>{
     if(reg.active)return reg;
     const worker=reg.installing||reg.waiting;
     if(!worker)throw new Error('The notification service worker did not start.');
     return new Promise((resolve,reject)=>{
       const cleanup=()=>{clearTimeout(timeout);worker.removeEventListener('statechange',onStateChange)};
       const timeout=setTimeout(()=>{cleanup();reject(new Error('The notification service worker did not activate in time.'))},4000);
       const onStateChange=()=>{if(worker.state==='activated'){cleanup();resolve(reg)}else if(worker.state==='redundant'){cleanup();reject(new Error('The notification service worker failed to install.'))}};
       worker.addEventListener('statechange',onStateChange);
     });
   });
   let timeout;
   const bounded=Promise.race([registration,new Promise((_,reject)=>{timeout=setTimeout(()=>reject(new Error('The browser did not finish setting up its notification service worker.')),4000)})]).finally(()=>clearTimeout(timeout));
   browserServiceWorkerReady=bounded.catch(error=>{browserServiceWorkerReady=null;throw error});
 }
 return browserServiceWorkerReady;
}
async function showBrowserNotification(title,options){
 if(!('Notification'in window))throw new Error('This browser does not support notifications.');
 if(Notification.permission!=='granted')throw new Error(`Notification permission is ${Notification.permission}.`);
 if(notificationDeliveryMode()==='page'){
   new Notification(title,options);
   return;
 }
 if('serviceWorker'in navigator){
   try{
     const registration=await ensureBrowserServiceWorker();
     if(typeof registration.showNotification==='function')return registration.showNotification(title,options);
   }catch(error){
     try{new Notification(title,options);return}
     catch(fallbackError){throw new Error(`Service-worker notification failed: ${String(error.message||error)} Page notification fallback failed: ${String(fallbackError.message||fallbackError)}`)}
   }
 }
 new Notification(title,options);
}
function reportBrowserNotificationFailure(error){
 console.error('Browser notification could not be displayed.',error);
 const status=document.getElementById('v12NativeDiag')||document.getElementById('nativeReminderStatus');
 if(status)status.textContent=`Browser notification failed: ${String(error?.message||error)}. Check this site's notification permission. Spoken reminders still work while the app remains open.`;
}
let buttonTapAudioErrorReported=false;
function reportButtonTapAudioError(error){if(buttonTapAudioErrorReported)return;buttonTapAudioErrorReported=true;console.warn('Button tap sound is unavailable; button actions remain enabled.',error)}
function playButtonTap(){
 try{
  const AudioContextClass=window.AudioContext||window.webkitAudioContext;
  if(!AudioContextClass)return;
  if(!webAudioCtx)webAudioCtx=new AudioContextClass();
  if(webAudioCtx.state==='suspended')webAudioCtx.resume().catch(reportButtonTapAudioError);
  const now=webAudioCtx.currentTime,oscillator=webAudioCtx.createOscillator(),gain=webAudioCtx.createGain();
  oscillator.type='sine';
  oscillator.frequency.setValueAtTime(1150,now);
  gain.gain.setValueAtTime(.0001,now);
  gain.gain.exponentialRampToValueAtTime(.045,now+.006);
  gain.gain.exponentialRampToValueAtTime(.0001,now+.05);
  oscillator.connect(gain);
  gain.connect(webAudioCtx.destination);
  oscillator.onended=()=>{oscillator.disconnect();gain.disconnect()};
  oscillator.start(now);
  oscillator.stop(now+.05);
 }catch(error){reportButtonTapAudioError(error)}
}
function buttonClickFeedback(event){
 const target=event.target;
 if(!(target instanceof Element))return;
 const button=target.closest('button');
 if(!button||button.disabled||button.getAttribute('aria-disabled')==='true')return;
 playButtonTap();
}
function primeWebReminderAudio(){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;if(!webAudioCtx)webAudioCtx=new AC();if(webAudioCtx.state==='suspended')webAudioCtx.resume()}catch(e){}}
function webReminderBeep(){try{primeWebReminderAudio();if(!webAudioCtx)return;const o=webAudioCtx.createOscillator(),g=webAudioCtx.createGain();o.type='sine';o.frequency.value=880;g.gain.setValueAtTime(.0001,webAudioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.12,webAudioCtx.currentTime+.02);g.gain.exponentialRampToValueAtTime(.0001,webAudioCtx.currentTime+.55);o.connect(g).connect(webAudioCtx.destination);o.start();o.stop(webAudioCtx.currentTime+.6)}catch(e){}}
function webNotify(item){
 const body=`After 5 minutes your next task is ${item.name}. It starts at ${item.start}.`;
 webReminderBeep();
 if(state.settings.voice!==false)speakReminder(`After five minutes, your next task is ${item.name}.`);
 if('Notification'in window&&Notification.permission==='granted')showBrowserNotification('Japan Lock-In — Next Task',{body,tag:'jl-'+item.id,renotify:true}).catch(reportBrowserNotificationFailure);
}
function scheduleWebReminders(){
 for(const timer of webReminderTimers.values())clearTimeout(timer);
 webReminderTimers.clear();
 const voiceAvailable=state.settings.voice!==false&&('speechSynthesis'in window||typeof window.AndroidBridge?.speak==='function');
 const notificationsAvailable='Notification'in window&&Notification.permission==='granted';
 if(!window.AndroidBridge?.scheduleReminders&&(voiceAvailable||notificationsAvailable)){
   const now=Date.now(),today=dateISO();
   for(let i=0;i<8;i++){
     const d=addDaysISO(today,i);
     for(const t of tasksFor(d)){
       const r=getRec(d,t.id);
       if(r.status==='done'||r.status==='missed'||r.status==='running')continue;
       if(t.prayer&&!prayerTimes(d))continue;
       const at=dhakaDate(d,r.plannedStart??t.start).getTime()-300000,key=d+'_'+t.id;
       if(at<=now+1500||at-now>8*24*60*60*1000||webReminderTimers.has(key))continue;
       webReminderTimers.set(key,setTimeout(()=>{
         webReminderTimers.delete(key);
         webNotify({id:key,name:t.name,start:time12(r.plannedStart??t.start)});
         scheduleWebReminders();
       },at-now));
     }
   }
 }
 Finance.scheduleBrowserReminders();
}
function reminderPayload(){const out=[];const today=dateISO();for(let i=0;i<14;i++){const d=addDaysISO(today,i);const ts=tasksFor(d);for(const t of ts){const r=getRec(d,t.id);if(t.prayer&&!prayerTimes(d))continue;const start=dhakaDate(d,r.plannedStart??t.start).getTime();const at=start-5*60000;if(at>Date.now()-60000)out.push({id:d+'_'+t.id,time:at,name:t.name,start:time12(t.start),date:d});}}return [...out,...Finance.nativeReminderPayload()].sort((a,b)=>a.time-b.time).slice(0,200)}
function syncNativeReminders(){try{if(window.AndroidBridge?.saveVoicePreference)window.AndroidBridge.saveVoicePreference(state.settings.voice!==false);const payload=reminderPayload();if(window.AndroidBridge?.scheduleReminders)window.AndroidBridge.scheduleReminders(JSON.stringify(payload));}catch(e){console.error('Native reminder scheduling failed.',e)}scheduleWebReminders()}
function updateLiveTaskUI(){const runs=runningTasks();for(const run of runs){const r=run.r,t=run.t,plannedMin=Number(r.plannedDur??t.dur)||0,sec=Math.max(0,Math.round((Date.now()-new Date(r.actualStart))/1000)),startMs=windowStartMs(run.date,t,r),endMs=windowEndMs(run.date,t,r),now=Date.now(),pct=plannedMin>0?Math.min(100,Math.max(0,(now-startMs)/(endMs-startMs)*100)):0,overtime=now>=endMs;const timer=document.getElementById('activeTimer_'+t.id);if(timer)timer.textContent=Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0');const fill=document.getElementById('runFill_'+t.id),bar=document.getElementById('runProgress_'+t.id),status=document.getElementById('runStatus_'+t.id);if(fill)fill.style.width=pct.toFixed(1)+'%';if(bar)bar.classList.toggle('overtime',overtime);if(status){status.classList.toggle('overtimebox',overtime);status.textContent=overtime?'Task overtime — '+formatDuration(Math.max(1,Math.ceil((now-endMs)/60000)))+' past the scheduled end time.':'In progress — '+formatDuration(Math.floor(sec/60))+' actual elapsed · '+formatDuration(Math.max(0,Math.ceil((endMs-now)/60000)))+' until scheduled end.';}}}
