function gameBand(level){return GAME_LEVELS.find(x=>level<=x.max)||GAME_LEVELS[GAME_LEVELS.length-1]}
function gameLevelForDay(day=currentDay()){return Math.min(100,Math.max(1,Math.ceil(day/180*100)))}
function packForDay(day=currentDay()){
 if(KANA_PACKS[day])return KANA_PACKS[day].map(([jp,en])=>({jp,en}));
 if(KANJI_PACKS[day])return KANJI_PACKS[day].map(([jp,en])=>({jp,en}));
 if(day>=22&&day<=42){const base=day%2===0?[['これ','this'],['それ','that'],['ここ','here'],['どこ','where'],['なに','what']]:[['ありがとう','thank you'],['すみません','excuse me'],['お願いします','please'],['日本','Japan'],['日本語','Japanese']];return base.map(([jp,en])=>({jp,en}));}
 const idx=Math.max(0,Math.min(CORE_PACKS.length-1,Math.floor((day-91)/2)));return CORE_PACKS[idx].map(([jp,en])=>({jp,en}));
}
function levelPack(level){
 const idx=(level-1)%CORE_PACKS.length;let base=CORE_PACKS[idx].map(([jp,en])=>({jp,en}));
 if(level<=28){const d=Math.max(1,Math.min(28,level));base=packForDay(d)}
 return base;
}
function shuffle(a){return a.map(x=>[Math.random(),x]).sort((x,y)=>x[0]-y[0]).map(x=>x[1])}
function norm(s){return String(s||'').toLowerCase().normalize('NFKC').replace(/[\s。、！？!?.,'"“”‘’]/g,'').trim()}
function dailyGameState(){const d=dateISO();state.daily[d]=state.daily[d]||{};state.daily[d].games=state.daily[d].games||{played:0,correct:0,wrong:0,level:gameLevelForDay()};return state.daily[d].games}
function gameLimit(){return Number(state.settings.gameLimit||20)}
function gameRemaining(){const g=dailyGameState();return Math.max(0,gameLimit()-g.played)}
function makeQuestion(kind,level){
 const pack=shuffle(levelPack(level));const item=pack[0];const all=pack;
 if(kind==='match'||kind==='choice'){
  const opts=shuffle([item,...shuffle(all.filter(x=>x.jp!==item.jp)).slice(0,3)]);return {kind,jp:item.jp,en:item.en,opts:opts.map(x=>x.en)};
 }
 if(kind==='type')return {kind,jp:item.jp,en:item.en,answer:item.jp};
 if(kind==='translate')return {kind,jp:item.jp,en:item.en,answer:item.en};
 if(kind==='speak')return {kind,jp:item.jp,en:item.en,answer:item.jp};
 if(kind==='write')return {kind,jp:item.jp,en:item.en,answer:item.jp};
 return {kind:'mock',sub:makeQuestion('choice',level)};
}
function renderGames(){
 if(planNotStarted()){document.getElementById('games').innerHTML=`<div class="card hero"><div class="pill" style="background:rgba(255,255,255,.16);color:#fff">🎮 GAMES LOCKED</div><h2 style="font-size:25px;margin:10px 0 5px">Games start with Day 1</h2><p class="muted">Your plan starts on ${esc(dateLabel(state.startDate))}.</p></div>`;return;}
 const day=currentDay(),level=gameLevelForDay(day),band=gameBand(level),g=dailyGameState(),rem=gameRemaining(),pack=packForDay(day);
 const levels=Array.from({length:100},(_,i)=>i+1).map(l=>`<button class="levelbox ${l<=level?'unlocked':''} ${l===level?'current':''}" onclick="selectGameLevel(${l})">${l}</button>`).join('');
 document.getElementById('games').innerHTML=`<div class="card gamehero fadein"><div class="sectiontitle"><div><div class="pill" style="background:rgba(255,255,255,.15);color:#fff">🎮 DAILY JAPANESE GAMES</div><h2 style="font-size:26px;margin:10px 0 5px">Level ${level} · ${esc(band.band)}</h2><div class="muted">Today’s material only · Day ${day} / 180</div></div><div class="ring">${g.played}/${gameLimit()}</div></div><div class="progress" style="margin-top:14px;background:rgba(255,255,255,.18)"><i style="width:${Math.min(100,g.played/gameLimit()*100)}%"></i></div><p style="margin-bottom:0;color:#e0e7ff">${rem} questions left today · ${g.correct} correct · ${g.wrong} wrong</p></div>
 <div class="card"><div class="sectiontitle"><div><h2 style="margin:0">Today’s learning pack</h2><div class="muted">These items come from today’s roadmap.</div></div><button class="soft" onclick="startGamesForToday()">Start daily game</button></div><div class="gamegrid" style="margin-top:12px">${pack.map((x,i)=>`<div class="gamecard"><div class="mini">ITEM ${i+1}</div><div style="font-size:26px;font-weight:950">${esc(x.jp)}</div><div class="muted">${esc(x.en)}</div></div>`).join('')}</div></div>
 <div class="gamegrid"><div class="gamecard"><h3 style="margin-top:0">🧠 Match / Meaning</h3><p class="muted">Choose the English meaning.</p><button onclick="startGame('choice')">Play</button></div><div class="gamecard"><h3 style="margin-top:0">⌨️ Recall / Type</h3><p class="muted">See the meaning and type Japanese.</p><button onclick="startGame('type')">Play</button></div><div class="gamecard"><h3 style="margin-top:0">🔊 Speak & Repeat</h3><p class="muted">Hear Japanese, say it, then type it.</p><button onclick="startGame('speak')">Play</button></div><div class="gamecard"><h3 style="margin-top:0">✍️ Finger Writing</h3><p class="muted">Draw it, then Validate.</p><button onclick="startGame('write')">Play</button></div><div class="gamecard"><h3 style="margin-top:0">🌎 Translation</h3><p class="muted">Translate Japanese into English.</p><button onclick="startGame('translate')" ${level<50?'disabled':''}>${level<50?'Unlocks at L50':'Play'}</button></div><div class="gamecard"><h3 style="margin-top:0">🧪 Daily Mock Test</h3><p class="muted">Mixed questions.</p><button onclick="startGame('mock')">Play</button></div></div>
 <div class="card"><div class="sectiontitle"><div><h2 style="margin:0">100-level progression</h2><div class="muted">Levels unlock with the roadmap.</div></div><span class="pill">L${level}</span></div><div class="levelmap" style="margin-top:12px">${levels}</div></div><div id="gamePanel"></div>`;
}
let gameSession=null;
function selectGameLevel(level){if(level>gameLevelForDay())return alert('This level unlocks later as your roadmap advances.');const g=dailyGameState();g.level=level;save();renderGames()}
function startGamesForToday(){document.querySelector('[data-tab="games"]')?.click();setTimeout(()=>startGame('choice'),50)}
function startGame(kind){if(gameRemaining()<=0)return alert('Daily game limit reached. Come back tomorrow.');let level=dailyGameState().level||gameLevelForDay();if(kind==='translate'&&level<50)return alert('Translation mode unlocks at Level 50.');gameSession={kind,level,step:0,score:0,total:Math.min(5,gameRemaining()),q:null,answered:false};drawGamePanel()}
function speakJapanese(textToSay){try{if(window.AndroidBridge?.speak){window.AndroidBridge.speak(textToSay);return}if('speechSynthesis'in window){window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(textToSay);u.lang='ja-JP';u.rate=.82;window.speechSynthesis.speak(u)}}catch(e){}}
function drawGamePanel(){const el=document.getElementById('gamePanel');if(!el||!gameSession)return;const {kind,level,step,total}=gameSession;if(step>=total){finishGame();return}const q=gameSession.q||makeQuestion(kind==='mock'?(step%2?'type':'choice'):kind,level);gameSession.q=q;let body='';if(q.kind==='choice')body=`<div class="gameprompt">${esc(q.jp)}</div><p class="muted">Choose the meaning.</p><div class="answergrid">${q.opts.map((o,i)=>`<button class="choice" onclick="answerChoice(this,${i})">${esc(o)}</button>`).join('')}</div>`;if(q.kind==='type')body=`<div class="gameprompt">${esc(q.en)}</div><p class="muted">Type the Japanese answer.</p><input id="gameInput" autocomplete="off" inputmode="text" placeholder="日本語"><div class="actions" style="margin-top:10px"><button onclick="answerText()">Check</button></div>`;if(q.kind==='speak')body=`<div class="gameprompt">${esc(q.jp)}</div><div class="actions" style="justify-content:center;margin:12px 0"><button class="ghost" onclick="speakJapanese('${esc(q.jp).replace(/'/g,"\\'")}')">🔊 Hear</button><button class="soft" onclick="startSpeechRecognition()">🎙️ Speak</button></div><input id="gameInput" autocomplete="off" inputmode="text" placeholder="Type what you said in Japanese"><div class="actions" style="margin-top:10px"><button onclick="answerText()">Check</button></div><div id="speechStatus" class="mini" style="margin-top:8px">Voice recognition is optional.</div>`;if(q.kind==='translate')body=`<div class="gameprompt">${esc(q.jp)}</div><p class="muted">Translate into English.</p><input id="gameInput" autocomplete="off" placeholder="English meaning"><div class="actions" style="margin-top:10px"><button onclick="answerText()">Check</button></div>`;if(q.kind==='write')body=`<div class="gameprompt" style="display:grid;gap:6px"><div style="font-size:44px;color:#0f172a;font-weight:900;opacity:1">${esc(q.jp)}</div><div class="muted" style="font-size:12px">Write the character below.</div></div><div class="canvaswrap" style="margin-top:10px"><canvas id="writeCanvas" class="writecanvas" width="640" height="640"></canvas></div><div class="actions" style="margin-top:10px"><button class="ghost" onclick="clearWriteCanvas()">Clear</button><button onclick="scoreWriting()">Validate</button></div><div id="writeResult" class="mini" style="margin-top:8px">Write in black, then Validate. Android uses native Japanese recognition; web uses the same stroke-data visual check.</div>`;el.innerHTML=`<div class="card fadein"><div class="sectiontitle"><div><h2 style="margin:0">${q.kind==='write'?'✍️ Finger Writing':q.kind==='translate'?'🌎 Translation':q.kind==='speak'?'🔊 Speak & Type':'🎯 Game'}</h2><div class="muted">Question ${step+1} / ${total} · Level ${level}</div></div><span class="pill">Score ${gameSession.score}</span></div>${body}<div id="gameFeedback" style="margin-top:10px"></div></div>`;if(q.kind==='write')setupWriteCanvas()}
function gradeGame(correct,message){if(!gameSession||gameSession.answered)return;gameSession.answered=true;const g=dailyGameState();g.played++;if(correct)g.correct++;else g.wrong++;save();gameSession.score+=correct?1:0;const p=document.getElementById('gameFeedback');if(p)p.innerHTML=`<div class="${correct?'successbox':'dangerbox'}"><b>${correct?'Correct ✅':'Not correct ❌'}</b>${message?' '+esc(message):''}<div class="actions" style="margin-top:10px"><button onclick="nextGameQuestion()">Next →</button></div></div>`;document.querySelectorAll('#gamePanel .choice').forEach(b=>b.disabled=true)}
function nextGameQuestion(){if(!gameSession||!gameSession.answered)return;gameSession.step++;gameSession.q=null;gameSession.answered=false;drawGamePanel()}
function answerChoice(btn,idx){if(!gameSession||gameSession.answered)return;const q=gameSession.q,chosen=btn.textContent,ok=norm(chosen)===norm(q.en);document.querySelectorAll('#gamePanel .choice').forEach(b=>{b.disabled=true;if(norm(b.textContent)===norm(q.en))b.classList.add('correct')});btn.classList.add(ok?'correct':'wrong');gradeGame(ok,ok?'':'Correct answer: '+q.en)}
function answerText(){if(!gameSession||gameSession.answered)return;const q=gameSession.q,input=document.getElementById('gameInput');if(!input)return;const val=input.value;const ok=norm(val)===norm(q.answer);input.disabled=true;gradeGame(ok,ok?'':'Correct answer: '+q.answer)}
function finishGame(){const panel=document.getElementById('gamePanel');if(!panel)return;const score=gameSession.score,total=gameSession.total;gameSession=null;panel.innerHTML=`<div class="card successbox fadein"><h2 style="margin-top:0">Session complete 🎉</h2><p>You scored <b>${score}/${total}</b>. ${gameRemaining()} daily questions remain.</p><button onclick="startGame('choice')">Play another set</button></div>`}
function setupWriteCanvas(){const c=document.getElementById('writeCanvas');if(!c)return;const ctx=c.getContext('2d');ctx.lineWidth=20;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#111827';let drawing=false;window.currentWritingStrokes=[];let stroke=null;const pos=e=>{const r=c.getBoundingClientRect();return {x:(e.clientX-r.left)*c.width/r.width,y:(e.clientY-r.top)*c.height/r.height}};const down=e=>{drawing=true;stroke=[];const p=pos(e);stroke.push([p.x,p.y,Date.now()]);window.currentWritingStrokes.push(stroke);ctx.beginPath();ctx.moveTo(p.x,p.y);e.preventDefault()};const move=e=>{if(!drawing)return;const p=pos(e);stroke.push([p.x,p.y,Date.now()]);ctx.lineTo(p.x,p.y);ctx.stroke();e.preventDefault()};const up=e=>{drawing=false;stroke=null;e.preventDefault()};['pointerdown','pointermove','pointerup','pointercancel'].forEach(ev=>c.addEventListener(ev,ev==='pointerdown'?down:ev==='pointermove'?move:up))}
function clearWriteCanvas(){const c=document.getElementById('writeCanvas');if(c)c.getContext('2d').clearRect(0,0,c.width,c.height);window.currentWritingStrokes=[];const r=document.getElementById('writeResult');if(r)r.textContent='Draw the target, then Validate.'}
function scoreWriting(){if(!gameSession||gameSession.answered)return;const result=document.getElementById('writeResult');if(!window.currentWritingStrokes||!window.currentWritingStrokes.length){if(result)result.textContent='Nothing detected. Draw the character first.';return;}const target=gameSession.q.jp;try{if(window.AndroidBridge?.recognizeHandwriting){if(result)result.textContent='Recognizing handwriting…';window.AndroidBridge.recognizeHandwriting(JSON.stringify(window.currentWritingStrokes),target);return;}const ok=browserVisualWritingCheck(target);if(ok){if(result)result.innerHTML='<div class="successbox"><b>✅ Looks correct</b><div class="mini">Stroke shape is close enough to the target.</div></div>';gradeGame(true,'Writing check passed.');}else{if(result)result.innerHTML='<div class="dangerbox"><b>❌ Try again</b><div class="mini">The stroke shape does not match the target closely enough.</div></div>';gradeGame(false,'Web writing check did not match the target.');}}catch(e){if(result)result.textContent='Writing validation failed. Please try again.'}}
function browserVisualWritingCheck(target){const c=document.getElementById('writeCanvas');if(!c||!window.currentWritingStrokes?.length)return false;const off=document.createElement('canvas');off.width=160;off.height=160;const o=off.getContext('2d');o.fillStyle='#fff';o.fillRect(0,0,160,160);o.fillStyle='#111827';o.font='700 120px sans-serif';o.textAlign='center';o.textBaseline='middle';o.fillText(target,80,84);const user=document.createElement('canvas');user.width=160;user.height=160;const u=user.getContext('2d');u.fillStyle='#fff';u.fillRect(0,0,160,160);u.strokeStyle='#111827';u.lineWidth=6;u.lineCap='round';u.lineJoin='round';for(const stroke of window.currentWritingStrokes){if(!stroke?.length)continue;u.beginPath();stroke.forEach((pt,i)=>{const x=(pt[0]/c.width)*160,y=(pt[1]/c.height)*160;i?u.lineTo(x,y):u.moveTo(x,y)});u.stroke();}const a=o.getImageData(0,0,160,160).data,b=u.getImageData(0,0,160,160).data;let inter=0,ua=0,ub=0;for(let i=3;i<a.length;i+=4){const aa=a[i]>50,bb=b[i]>50;if(aa)ua++;if(bb)ub++;if(aa&&bb)inter++;}if(ub<35||window.currentWritingStrokes.length>12)return false;const dice=(2*inter)/(ua+ub||1);const fillRatio=ub/(ua||1);return dice>=0.18&&fillRatio>=0.35&&fillRatio<=2.4;}
window.__nativeWritingResult=function(recognized,candidates){if(!gameSession||gameSession.answered)return;const target=gameSession.q.jp,ok=norm(recognized)===norm(target);const r=document.getElementById('writeResult');if(r)r.innerHTML=ok?`<div class="successbox"><b>✅ Recognized: ${esc(recognized)}</b><div class="mini">Correct character.</div></div>`:`<div class="dangerbox"><b>❌ Recognized: ${esc(recognized||'nothing')}</b><div class="mini">Target: ${esc(target)} · Try again with the correct strokes.</div></div>`;if(ok)gradeGame(true,'Native handwriting recognized correctly.');else gradeGame(false,'Native recognizer did not match the target.');}
function startSpeechRecognition(){const R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R){const s=document.getElementById('speechStatus');if(s)s.textContent='Voice recognition is not available in this browser. Type after speaking.';return}const r=new R();r.lang='ja-JP';r.interimResults=false;r.maxAlternatives=1;r.onresult=e=>{const text=e.results[0][0].transcript;const i=document.getElementById('gameInput');if(i)i.value=text;const s=document.getElementById('speechStatus');if(s)s.textContent='Heard: '+text};r.onerror=()=>{const s=document.getElementById('speechStatus');if(s)s.textContent='Could not access speech recognition.'};r.start()}

function editTemplateTask(day,id){const arr=state.weeklyTemplates[day]||[];const t=arr.find(x=>x.id===id);if(!t)return;let name=prompt('Task name',t.name);if(name===null)return;let st=prompt('Start time (e.g. 8:00 PM or 20:00)',time12(t.start||'00:00'));if(st===null)return;const parsed=parseClockInput(st);if(parsed===null)return alert('Use a time like 8:00 PM or 20:00.');let dur=prompt('Duration in minutes',t.dur);if(dur===null)return;const n=Number(dur);if(!Number.isFinite(n)||n<1)return alert('Duration must be at least 1 minute.');t.name=name.trim()||t.name;t.start=time(parsed);t.manualName=!!t.prayer;t.manualStart=!!t.prayer;t.dur=Math.round(n);setWeekdayTemplate(day,arr)}
function addTemplateTask(day){const arr=state.weeklyTemplates[day]||[];const name=prompt('New task name');if(!name)return;const st=prompt('Start time (e.g. 8:00 PM or 20:00)','8:00 PM');if(!st)return;const parsed=parseClockInput(st);if(parsed===null)return alert('Use a time like 8:00 PM or 20:00.');const d=Number(prompt('Duration in minutes','20'));if(!Number.isFinite(d)||d<1)return alert('Duration must be at least 1 minute.');arr.push({id:'custom-'+Date.now(),name:name.trim(),start:time(parsed),dur:Math.round(d),kind:'custom',flex:true});setWeekdayTemplate(day,arr)}
function deleteTemplateTask(day,id){const arr=state.weeklyTemplates[day]||[];const t=arr.find(x=>x.id===id);if(!t)return;if(t.prayer)return alert('Prayer anchors cannot be deleted. You can edit their name, time and duration.');if(!confirm('Delete '+t.name+' from the '+day+' template?'))return;state.weeklyTemplates[day]=arr.filter(x=>x.id!==id);setWeekdayTemplate(day,state.weeklyTemplates[day])}
function renderProgress(){
 if(planNotStarted()){document.getElementById('progress').innerHTML=`<div class="card lockedbox">🔒 Progress is locked. Your 180-day journey starts <b>${esc(dateLabel(state.startDate))}</b>.</div>`;return;}
 const ps=progressStats(),n=currentDay(),today=dateISO(),todayC=completion(today),ws=weeklyStats(today),levelPct=Math.round(ps.inLevel/120*100),weeks=[];
 const start=weekStartSat(today);
 for(let i=0;i<6;i++){const d=addDaysISO(start,-7*(5-i));const st=weeklyStats(d);if(st.possible)weeks.push(st);}
 const journey=[['🇧🇩','Bangladesh','Your starting point'],['ひらがな','Hiragana','Days 1–10'],['カタカナ','Katakana','Days 11–21'],['N5','N5 Core','Days 22–42'],['漢字','Kanji','Days 43–90'],['N4','N4 Core','Days 91–130'],['JFT','JFT-Basic / N4','Days 131–160'],['SSW','SSW Japanese','Days 161–180'],['🇯🇵','Japan','Long-term destination']];
 const journeyHtml=journey.map((x,i)=>`<div class="stat" style="padding:10px;min-width:0"><div style="font-size:22px">${x[0]}</div><b style="font-size:14px">${x[1]}</b><div class="tiny">${x[2]}</div>${i>0&&i<8?`<div class="mini" style="margin-top:5px">${n>=([1,11,22,43,91,131,161][i-1]||999)?'Unlocked':'Locked'}</div>`:''}</div>`).join('');
 const weekBars=weeks.length?weeks.map(w=>`<div style="margin:9px 0"><div class="sectiontitle"><span class="mini">${esc(dateLabel(w.start))}</span><b>${w.score}%</b></div><div class="progress"><i style="width:${w.score}%"></i></div><div class="tiny">${w.done} done · ${w.missed} missed</div></div>`).join(''):'<p class="muted">Complete tasks to create your first weekly score.</p>';
 document.getElementById('progress').innerHTML=`
 <div class="card hero fadein"><div class="pill">LOCK-IN PROGRESS</div><h2 style="font-size:28px;margin:10px 0 4px">Command Center Progress</h2><div class="muted">Day ${n}/180 · Level ${ps.level} · ${ps.xp} XP</div><div class="xpbar" style="margin-top:14px"><i style="width:${levelPct}%"></i></div><div class="mini" style="margin-top:7px">${ps.inLevel}/120 XP to next level</div></div>
 <div class="stats"><div class="stat"><span class="tiny">TODAY</span><b>${todayC.pct}%</b></div><div class="stat"><span class="tiny">THIS WEEK</span><b>${ws.score}%</b></div><div class="stat"><span class="tiny">STREAK</span><b>${streakDays()}</b></div><div class="stat"><span class="tiny">PERFECT DAYS</span><b>${ps.perfect}</b></div></div>
 <div class="card"><div class="sectiontitle"><div><div class="pill">⚔ DAILY BOSS</div><h3 style="margin:8px 0 3px">Finish today's mission without a miss.</h3><div class="muted">${todayC.done}/${todayC.total} complete · ${todayC.missed} missed</div></div><span class="pill ${todayC.missed?'missed':'done'}">${todayC.missed?'INCOMPLETE':'ACTIVE'}</span></div><div class="progress" style="margin-top:10px"><i style="width:${todayC.pct}%"></i></div></div>
 <div class="card"><div class="sectiontitle"><div><div class="pill">🏆 WEEKLY BOSS</div><h3 style="margin:8px 0 3px">Target: 80%+</h3><div class="muted">Saturday → Friday discipline score.</div></div><b>${ws.score}%</b></div><div class="progress" style="margin-top:10px"><i style="width:${ws.score}%"></i></div>${isSaturday(today)&&ws.possible&&ws.score<80?`<div class="mission" style="margin-top:10px;padding:12px;border-radius:14px"><b>Recovery budget active.</b><div class="mini">Small recovery tasks use only safe free time. They do not cut sleep, prayer, office or core Japanese study.</div></div>`:''}</div>
 <div class="card"><h3 style="margin:0 0 4px">Weekly history</h3>${weekBars}</div>
 <div class="card"><div class="sectiontitle"><div><div class="pill">🗾 JAPAN JOURNEY</div><h3 style="margin:8px 0 3px">Bangladesh → Japan</h3><div class="muted">Your learning route from script foundations to SSW Japanese.</div></div></div><div class="stats" style="grid-template-columns:repeat(3,1fr);margin-top:12px">${journeyHtml}</div></div>
 <div class="card"><h3 style="margin:0 0 8px">🎯 What earns XP?</h3><div class="grid"><div class="notice"><b>Task complete</b><br>+10 XP · +1 bonus when finished without overtime.</div><div class="notice"><b>Japanese task</b><br>+3 bonus XP for roadmap-linked Japanese work.</div><div class="notice"><b>Perfect day</b><br>+25 XP when every scheduled task is completed.</div><div class="notice"><b>80%+ week</b><br>+50 XP weekly discipline bonus.</div></div></div>`;
}
function renderSchedule(){
 if(planNotStarted()){document.getElementById('schedule').innerHTML=`<div class="card lockedbox">🔒 Schedule is locked. Plans start from <b>${esc(dateLabel(state.startDate))}</b>.</div>`;return;}
 const today=dateISO();const blocks=DEFAULTS.weekdayOrder.map(day=>{const arr=state.weeklyTemplates[day]||[];const isToday=dayKey(today)===day;const preview=arr.slice().sort((a,b)=>mins(a.start||'00:00')-mins(b.start||'00:00')).map((t,i)=>`<div class="task"><div class="time">${time12(t.start||'00:00')}<br><small>${formatDuration(t.dur)}</small></div><div><b>${esc(t.name)}</b><br><span class="pill ${t.prayer?'anchor':''}">${t.prayer?(t.manualStart?'Prayer · manual':'Prayer · dynamic'):'Template'}</span></div><div class="actions"><button class="ghost" onclick="editTemplateTask('${day}','${t.id}')">Edit</button>${!t.prayer?`<button class="danger" onclick="deleteTemplateTask('${day}','${t.id}')">Delete</button>`:''}</div></div>`).join('');return `<details class="weekday" ${isToday?'open':''}><summary>${isToday?'⚡ ':''}${day} <span class="muted">· ${arr.length} tasks</span></summary><div class="inside">${preview}<div class="actions schedule-template-actions"><button class="soft" onclick="addTemplateTask('${day}')">＋ Add task</button><button class="ghost" onclick="copyWeekdayTemplate('${day}')">⇄ Copy to another day</button></div></div></details>`}).join('');
 document.getElementById('schedule').innerHTML=`<div class="card hero"><div class="pill">WEEKLY SCHEDULE ENGINE</div><h2 style="font-size:27px;margin:10px 0 4px">Saturday → Friday</h2><p class="muted">Each weekday is its own template. Use “Copy to another day” to reuse a routine without rebuilding it. Copying replaces that day’s regular tasks; its prayer tasks stay in place.</p></div><div class="card">${blocks}</div><div class="card"><h3 style="margin-top:0">Schedule rules</h3><p class="muted">Prayer tasks are editable. Manual prayer edits stay on that weekday and are not overwritten by later prayer refreshes. Friday and Saturday have separate routines. Future dates refresh from the edited template; locked historical records remain unchanged.</p></div>`;
}
function copyWeekdayTemplate(sourceDay){
 if(!DEFAULTS.weekdayOrder.includes(sourceDay))return alert('Choose a valid source day.');
 const destinations=DEFAULTS.weekdayOrder.filter(day=>day!==sourceDay);
 const choices=destinations.map((day,index)=>`${index+1}. ${day}`).join('\n');
 const selected=prompt(`Copy regular tasks from ${sourceDay} to which day?\n\n${choices}\n\nEnter the destination number:`);
 if(selected===null)return;
 const destination=destinations[Number(selected)-1];
 if(!destination)return alert('Choose one of the listed destination numbers.');
 const sourceTasks=(state.weeklyTemplates[sourceDay]||[]).filter(task=>!task.prayer);
 if(!sourceTasks.length)return alert(`${sourceDay} has no regular tasks to copy.`);
 const targetTasks=state.weeklyTemplates[destination]||[];
 const targetPrayerTasks=targetTasks.filter(task=>task.prayer);
 const targetRegularCount=targetTasks.length-targetPrayerTasks.length;
 if(!confirm(`Replace ${destination}'s ${targetRegularCount} regular task${targetRegularCount===1?'':'s'} with ${sourceDay}'s ${sourceTasks.length} regular task${sourceTasks.length===1?'':'s'}?\n\n${destination}'s prayer tasks will stay unchanged. Existing schedule history will not be deleted.`))return;
 const copiedTasks=sourceTasks.map((task,index)=>({
   ...structuredClone(task),
   id:`copy-${Date.now()}-${index}-${globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2,10)}`
 }));
 setWeekdayTemplate(destination,[...targetPrayerTasks,...copiedTasks]);
 alert(`${sourceDay}'s regular tasks were copied to ${destination}.`);
}
function doneAnyway(){return false}
function renderHistory(){
 const today=dateISO();
 const all=Object.keys(state.records).filter(d=>d<today&&state.records[d]&&Object.keys(state.records[d]).length).sort().reverse();
 const blocks=all.map(d=>{const tasks=tasksFor(d),recs=state.records[d]||{};let total=0;const rows=tasks.map(t=>{const r=recs[t.id];if(!r)return '';total+=r.actualDuration||0;const log=r.actualDuration!=null?`Actual ${formatDuration(r.actualDuration)} / planned ${formatDuration(r.plannedDur??t.dur)} · late start ${formatDuration(r.lateStartMin||0)} · overtime ${formatDuration(r.overtimeMin||0)}`:(r.status==='missed'&&r.reason)?`Reason: ${esc(r.reason)}`:`Planned ${formatDuration(r.plannedDur??t.dur)} · ${esc(r.status||'pending')}`;return `<div class="task"><div class="time">${r.actualStart?esc(new Date(r.actualStart).toLocaleTimeString('en-US',{timeZone:'Asia/Dhaka',hour:'numeric',minute:'2-digit'})):'—'}<br><small>${r.actualStop?esc(new Date(r.actualStop).toLocaleTimeString('en-US',{timeZone:'Asia/Dhaka',hour:'numeric',minute:'2-digit'})):'—'}</small></div><div><div class="name"><b>${esc(t.name)}</b> <span class="pill ${r.status==='done'?'done':r.status==='missed'?'missed':''}">${esc(r.status)}</span></div><div class="subtask">${t.prayer?'Prayer anchor · dynamic daily time':esc(t.kind)}</div><div class="tasklog">${log}</div></div><div></div></div>`}).join('');const complete=dayComplete(d);return `<details class="historyday"><summary>${complete?'✓ ':''}${esc(dateLabel(d))} <span class="muted">· ${Object.keys(recs).length} recorded · ${formatDuration(total)} tracked</span></summary><div style="padding:0 14px 10px">${rows||'<p class="muted">No task records.</p>'}</div></details>`}).join('');
 document.getElementById('history').innerHTML=`<div class="card"><div class="sectiontitle"><div><h2 style="margin:0">Daily history</h2><div class="muted">A day is added here only after that Bangladesh day has ended.</div></div></div>${blocks||'<p class="muted">No completed day is in history yet. Today will appear here after the day ends.</p>'}</div>`;
}
