function refreshNativeReminderStatus(){
 const el=document.getElementById('nativeReminderStatus');if(!el)return;
 if(window.AndroidBridge?.isNotificationEnabled&&window.AndroidBridge?.isExactAlarmGranted){
  const notifications=!!window.AndroidBridge.isNotificationEnabled(),exact=!!window.AndroidBridge.isExactAlarmGranted();
  el.textContent='Android notifications: '+(notifications?'ON':'OFF')+' · Exact alarms: '+(exact?'ON':'OFF')+(exact?'':' — grant “Alarms & reminders” for precise delivery.');
  el.className='mini '+(notifications&&exact?'success':'notice');
 }else{el.textContent='Browser mode: notifications depend on browser permission and the page remaining available for web reminders.';el.className='mini';}
 if(window.__nativeReminderErrorMessage)el.textContent+=' · '+window.__nativeReminderErrorMessage;
}
window.__nativeReminderPermissionResult=function(){refreshNativeReminderStatus();};
window.__nativeReminderError=function(message){window.__nativeReminderErrorMessage='Android reminder scheduling failed: '+String(message||'Unknown native scheduling error.');const el=document.getElementById('nativeReminderStatus')||document.getElementById('v12NativeDiag');if(el)el.textContent=window.__nativeReminderErrorMessage;};
function saveNotificationPrefs(){primeWebReminderAudio();state.settings.voice=document.getElementById('voicePref').value==='on';state.settings.sound=true;state.settings.notifications=true;try{if(window.AndroidBridge?.saveVoicePreference)window.AndroidBridge.saveVoicePreference(state.settings.voice)}catch(e){}save();syncNativeReminders();renderSettings();alert('Reminder settings saved.');}
function openNativeAlarmSettings(){try{if(window.AndroidBridge?.openExactAlarmSettings)window.AndroidBridge.openExactAlarmSettings();else alert('Open Android Settings → Special app access → Alarms & reminders for Japan Lock-In.');}catch(e){}}
function saveGameSettings(){const v=Math.max(5,Math.min(100,Number(document.getElementById('gameLimit').value)||20));state.settings.gameLimit=v;save();render()}
