function speakReminder(text){
  if(window.AndroidBridge?.speak){window.AndroidBridge.speak(text);return}
  if(!('speechSynthesis'in window)){console.error('Spoken reminders are unavailable in this browser.');return}
  const synthesis=window.speechSynthesis,utterance=new SpeechSynthesisUtterance(text);
  utterance.lang='en-US';utterance.rate=.9;utterance.volume=1;
  utterance.onerror=event=>console.error('Spoken reminder failed.',event.error||event);
  try{
    synthesis.cancel();
    synthesis.resume();
    synthesis.speak(utterance);
  }catch(error){console.error('Spoken reminder could not start.',error)}
}
